  "file_path": "/Users/parker/ErrorBoundary.tsx",
  "content": "import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    this.setState({ errorInfo });

    const log = {
      message: error.message,
      stack: error.stack,
      componentStack: errorInfo.componentStack,
      timestamp: new Date().toISOString(),
    };

    console.error('[ErrorBoundary]', log);
    this.props.onError?.(error, errorInfo);
  }

  private retry = (): void => {
    this.setState({ error: null, errorInfo: null });
  };

  render(): ReactNode {
    const { error, errorInfo } = this.state;

    if (error) {
      if (this.props.fallback) {
        return this.props.fallback(error, this.retry);
      }

      return (
        <DefaultFallback
          error={error}
          errorInfo={errorInfo}
          onRetry={this.retry}
        />
      );
    }

    return this.props.children;
  }
}

interface DefaultFallbackProps {
  error: Error;
  errorInfo: ErrorInfo | null;
  onRetry: () => void;
}

function DefaultFallback({ error, errorInfo, onRetry }: DefaultFallbackProps) {
  const [showDetails, setShowDetails] = React.useState(false);

  return (
    <div role="alert" style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>Something went wrong</h2>
        <p style={styles.message}>{error.message}</p>

        <div style={styles.actions}>
          <button onClick={onRetry} style={styles.retryButton}>
            Try again
          </button>
          <button
            onClick={() => setShowDetails((v) => !v)}
            style={styles.detailsButton}
          >
            {showDetails ? 'Hide' : 'Show'} details
          </button>
        </div>

        {showDetails && (
          <pre style={styles.details}>
            {error.stack}
            {errorInfo?.componentStack
              ? `\n\nComponent stack:${errorInfo.componentStack}`
              : ''}
          </pre>
        )}
      </div>
    </div>
  );
}

